            ["closed_menu"] = new[] { "恢复已关闭会话", "Restore closed session", "還原已關閉的工作階段", "Geschlossene Sitzung wiederherstellen", "閉じたセッションを復元", "Restaurer une session fermée", "닫힌 세션 복원", "Restaurar sesión cerrada", "Ripristina sessione chiusa" },
